"""Original 2014 origin summaries and factual construction data, separate from SRD files."""
import json,pathlib
root=pathlib.Path(__file__).resolve().parents[1];items=[]
skills=['acrobatics','animalHandling','arcana','athletics','deception','history','insight','intimidation','investigation','medicine','nature','perception','performance','persuasion','religion','sleightOfHand','stealth','survival']
languages=['common','dwarvish','elvish','giant','gnomish','goblin','halfling','orc','abyssal','celestial','draconic','deep-speech','infernal','primordial','sylvan','undercommon']
tools=['alchemists-supplies','brewers-supplies','calligraphers-supplies','carpenters-tools','cartographers-tools','cobblers-tools','cooks-utensils','glassblowers-tools','jewelers-tools','leatherworkers-tools','masons-tools','painters-supplies','potters-tools','smiths-tools','tinkers-tools','weavers-tools','woodcarvers-tools']
instruments=['bagpipes','drum','dulcimer','flute','lute','lyre','horn','pan-flute','shawm','viol'];games=['dice-set','dragonchess-set','playing-card-set','three-dragon-ante-set']
def source(src):return {'kind':'reference','document':{'phb14':'Manuel des joueurs2014','ravenloft':'Van Richten’s Guide to Ravenloft2021','motm':'Monsters of the Multiverse2022','volo':'Volo’s Guide to Monsters2016, errata2020'}[src],'license':'Pilot20-original-summary','url':'https://www.dndbeyond.com/sources/dnd/'+{'phb14':'phb-2014','ravenloft':'vrgtr','motm':'motm','volo':'vgTM'}[src]}
def entry(id,typ,fr,en,src,**data):
 e={'id':id,'type':typ,'name':{'fr':fr,'en':en},'source':source(src),'data':{'ruleset':'dnd5e-2014','rulesSourceId':src,'automation':{'status':'partial','handler':None,'limits':['Conditional traits require player/GM adjudication.']},**data}};items.append(e);return e
def choice(key,kind,count,options,fr,**extra):return {'key':key,'kind':kind,'count':count,'options':options,'label':{'fr':fr,'en':key.replace('-',' ').title()},**extra}
def trait(key,fr,en,note,**extra):return {'id':key,'name':{'fr':fr,'en':en},'description':note,'automation':'manual',**extra}
def bg(key,fr,en,skill,prof,choices,note,gear,gold):
 return entry('phb14:background:'+key,'background',fr,en,'phb14',summary={'fr':note,'en':en+' background; 2014 rules.'},description=note,language='fr',skills=skill,proficiencies=prof,languages=[],choices=choices,equipment=[{'id':key+'-gear','name':{'fr':gear,'en':gear}},{'id':key+'-pouch','name':{'fr':'Bourse : '+str(gold)+' po','en':'Pouch: '+str(gold)+' gp'}}],feature={'id':key+'-feature','name':{'fr':fr+' — capacité d’historique','en':en+' background feature'},'description':note,'automation':'manual'})
bg('charlatan','Charlatan','Charlatan',['deception','sleightOfHand'],['disguise-kit','forgery-kit'],[],'Une fausse identité avec documents, relations et déguisements ; vous pouvez aussi imiter un écrit dont vous avez un exemple.','Vêtements de qualité, accessoires de déguisement et instrument de tricherie au choix',15)
criminal=bg('criminal','Criminel','Criminal',['deception','stealth'],['thieves-tools'],[choice('gaming-set','proficiency',1,games,'Jeu maîtrisé')],'Un contact fiable facilite vos échanges avec le milieu criminel, même à distance.','Pied-de-biche, vêtements ordinaires sombres avec capuche',15)
entertainer=bg('entertainer','Artiste','Entertainer',['acrobatics','performance'],['disguise-kit'],[choice('instrument','proficiency',1,instruments,'Instrument maîtrisé')],'Vous trouvez généralement le gîte et le couvert en échange de spectacles ; votre réputation peut ouvrir des portes auprès de votre public.','Instrument de musique, présent d’un admirateur, costume',15)
bg('folk-hero','Héros du peuple','Folk Hero',['animalHandling','survival'],['land-vehicles'],[choice('artisan-tool','proficiency',1,tools,'Outils d’artisan')],'Les gens du commun vous aident à vous abriter ou vous cacher, tant que vous ne les mettez pas en danger.','Outils d’artisan, pelle, pot en fer et vêtements ordinaires',10)
guild=bg('guild-artisan','Artisan de guilde','Guild Artisan',['insight','persuasion'],[],[choice('artisan-tool','proficiency',1,tools,'Outils d’artisan'),choice('language','language',1,languages,'Langue supplémentaire')],'La guilde offre contacts, soutien matériel et parfois juridique ; ses cotisations et obligations restent à respecter.','Outils d’artisan, lettre d’introduction de guilde, vêtements de voyage',15)
bg('hermit','Ermite','Hermit',['medicine','religion'],['herbalism-kit'],[choice('language','language',1,languages,'Langue supplémentaire')],'Votre isolement vous a révélé une découverte importante, à définir avec le MJ en lien avec la campagne.','Étui de notes ou prières, couverture d’hiver, vêtements ordinaires et matériel d’herboriste',5)
noble=bg('noble','Noble','Noble',['history','persuasion'],[],[choice('gaming-set','proficiency',1,games,'Jeu maîtrisé'),choice('language','language',1,languages,'Langue supplémentaire')],'Votre rang facilite l’accueil et l’accès à la haute société ; une audience avec un noble local peut être obtenue.','Vêtements de qualité, chevalière et document de lignée',25)
bg('outlander','Sauvageon','Outlander',['athletics','survival'],[],[choice('instrument','proficiency',1,instruments,'Instrument maîtrisé'),choice('language','language',1,languages,'Langue supplémentaire')],'Vous mémorisez bien les cartes et paysages ; dans un environnement qui le permet, vous trouvez nourriture et eau pour vous et cinq autres personnes.','Bâton, piège de chasse, trophée animal et vêtements de voyage',10)
bg('sage','Sage','Sage',['arcana','history'],[],[choice('languages','language',2,languages,'Langues supplémentaires')],'Lorsque vous ignorez une information, vous savez souvent où ou auprès de qui la chercher ; la réponse n’est pas forcément facile d’accès.','Encre, plume, petit couteau, lettre d’une question irrésolue et vêtements ordinaires',10)
sailor=bg('sailor','Marin','Sailor',['athletics','perception'],['navigators-tools','water-vehicles'],[],'Vos relations permettent généralement un passage en mer pour le groupe, avec service à bord et itinéraire à négocier.','Gourdin, corde de soie15 m, porte-bonheur et vêtements ordinaires',10)
bg('soldier','Soldat','Soldier',['athletics','intimidation'],['land-vehicles'],[choice('gaming-set','proficiency',1,games,'Jeu maîtrisé')],'Votre grade militaire donne une autorité et un accès appropriés auprès des membres de votre ancienne organisation.','Insigne de grade, trophée d’un ennemi, jeu et vêtements ordinaires',10)
bg('urchin','Enfant des rues','Urchin',['sleightOfHand','stealth'],['disguise-kit','thieves-tools'],[],'Votre connaissance des villes permet au groupe de parcourir les trajets urbains entre deux lieux deux fois plus vite, hors combat.','Petit couteau, carte de la ville, souris, souvenir familial et vêtements ordinaires',10)
for original,key,fr,en,note in [(criminal,'spy','Criminel (Espion)','Spy','Un réseau d’espionnage plutôt qu’un contact criminel sert de relais à vos messages et missions.'),(entertainer,'gladiator','Artiste (Gladiateur)','Gladiator','Vos prouesses martiales font office de spectacles. Un lieu accueillant ce type de combats peut vous héberger ; une arme inhabituelle et peu coûteuse remplace l’instrument dans votre équipement.'),(guild,'guild-merchant','Négociant de guilde','Guild Merchant','Variante marchande d’Artisan de guilde, avec soutien et obligations de guilde. Une langue supplémentaire peut remplacer l’outil ; une mule et une charrette peuvent remplacer les outils de l’équipement.'),(noble,'knight','Chevalier','Knight','Trois serviteurs loyaux et non combattants vous accompagnent, dont un écuyer. Ils s’occupent de tâches ordinaires et ne prennent pas de risques évidents pour vous.'),(sailor,'pirate','Pirate','Pirate','Votre réputation intimide les gens : de petites infractions peuvent rester sans dénonciation par peur. Ce n’est pas une immunité juridique ni un contrôle des réactions du MJ.')]:
 e=json.loads(json.dumps(original));e['id']='phb14:background:'+key;e['name']={'fr':fr,'en':en};e['data']['description']=e['data']['summary']['fr']=note;e['data']['feature']={'id':key+'-feature','name':{'fr':fr+' — capacité','en':en+' feature'},'description':note,'automation':'manual'};items.append(e)
 # Guild Merchant may explicitly choose a language instead of tools; model as two profiles below.
 if key=='guild-merchant':e['data']['choices']=[choice('trade-training','ancestry-option',1,['artisan','navigator','language'],'Formation de négociant'),choice('artisan-tool','proficiency',1,tools,'Outils d’artisan',requiresChoice={'key':'trade-training','optionId':'artisan'}),choice('navigator-tool','proficiency',1,['navigators-tools'],'Outils de navigateur',requiresChoice={'key':'trade-training','optionId':'navigator'}),choice('trade-language','language',1,languages,'Langue du commerce',requiresChoice={'key':'trade-training','optionId':'language'}),e['data']['choices'][1]]
entry('ravenloft:race:dhampir','race','Dhampire','Dhampir','ravenloft',bonuses={},flexibleAbilityBoosts=True,languages=['common'],speed=35,size='medium',sizes=['small','medium'],creatureType='humanoid',movementModes={'climb':35,'climbMatchesWalk':True},skills=[],proficiencies=[],choices=[choice('language','language',1,languages,'Langue supplémentaire'),choice('ancestral-skills','skill',2,skills,'Héritage ancestral — compétences')],subraces=[],traits=[trait('darkvision','Vision dans le noir18 m','Darkvision60 ft.','Pénombre comme lumière vive ; obscurité comme pénombre, en nuances de gris.'),trait('deathless-nature','Nature immortelle','Deathless Nature','Vous n’avez pas besoin de respirer.'),trait('spider-climb','Pattes d’araignée','Spider Climb','Votre vitesse d’escalade égale votre vitesse au sol.'),trait('spider-climb-hands-free','Escalade mains libres','Hands-free spider climb','Vous pouvez marcher sur les murs et plafonds en gardant les mains libres.',minimumCharacterLevel=3),trait('vampiric-bite','Morsure vampirique','Vampiric Bite','Arme naturelle courante maîtrisée : Constitution remplace Force pour l’attaque et les dégâts ;1d4 perforant+Constitution. Avantage aux attaques de morsure lorsque vous avez perdu au moins la moitié de vos PV.',activation={'cost':'action','target':'selected','maxTargets':1}),trait('bite-empowerment','Renforcement par la morsure','Bite empowerment','Après une morsure touchant une cible ni artificielle ni morte-vivante : récupérez les dégâts perforants infligés en PV, ou ajoutez-les au prochain test de caractéristique ou jet d’attaque. Bonus de maîtrise utilisations par repos long.',resource={'proficiency':True,'recovery':'long'})],description='Lignée Van Richten2021 pour règles2014. Les deux compétences correspondent à une création initiale ; une transformation conservant l’héritage d’une race précédente exige la vérification de cet héritage.',language='fr')
entry('volo:race:kobold','race','Kobold (Volo2016)','Kobold (Volo2016)','volo',bonuses={'dex':2},languages=['common','draconic'],speed=30,size='small',creatureType='humanoid',skills=[],proficiencies=[],choices=[],subraces=[],traits=[trait('darkvision','Vision dans le noir18 m','Darkvision60 ft.','Pénombre comme lumière vive, obscurité comme pénombre.'),trait('sunlight-sensitivity','Sensibilité au soleil','Sunlight Sensitivity','Désavantage aux attaques et tests visuels de Perception si vous ou la cible observée êtes directement au soleil.'),trait('pack-tactics','Tactique de groupe','Pack Tactics','Avantage à une attaque si un allié non neutralisé se trouve à1,50 m de la cible.'),trait('grovel-cower-beg','Implorer, ramper et supplier','Grovel, Cower, and Beg','Action : vos alliés ont l’avantage contre les ennemis qui vous voient à3 m de vous, jusqu’à la fin de votre prochain tour. Une utilisation par repos court ou long.',resource={'max':1,'recovery':'short'},activation={'cost':'action','target':'self','maxTargets':1})],description='Version2016 avec errata2020 : aucun malus de Force. Ne mélange pas les traits avec la version2022.',language='fr')
entry('motm:race:kobold','race','Kobold (MotM2022)','Kobold (MotM2022)','motm',bonuses={},flexibleAbilityBoosts=True,languages=['common'],speed=30,size='small',creatureType='humanoid',skills=[],proficiencies=[],choices=[choice('language','language',1,languages,'Langue supplémentaire'),choice('legacy','ancestry-option',1,['defiance','craftiness','draconic-sorcery'],'Héritage kobold'),choice('craftiness-skill','skill',1,['arcana','investigation','medicine','sleightOfHand','survival'],'Compétence d’Astuce',requiresChoice={'key':'legacy','optionId':'craftiness'}),choice('draconic-ability','ancestry-option',1,['int','wis','cha'],'Caractéristique de Sorcellerie draconique',requiresChoice={'key':'legacy','optionId':'draconic-sorcery'}),choice('draconic-cantrip','racial-spell',1,[],'Sort mineur de Sorcellerie draconique',classId='sorcerer',abilityChoiceKey='draconic-ability',requiresChoice={'key':'legacy','optionId':'draconic-sorcery'})],subraces=[],traits=[trait('darkvision','Vision dans le noir18 m','Darkvision60 ft.','Pénombre comme lumière vive, obscurité comme pénombre.'),trait('draconic-cry','Cri draconique','Draconic Cry','Action bonus : jusqu’au début de votre prochain tour, vous et vos alliés êtes avantagés aux attaques contre les ennemis à3 m qui peuvent vous entendre. Bonus de maîtrise utilisations par repos long.',resource={'proficiency':True,'recovery':'long'},activation={'cost':'bonus','target':'self','maxTargets':1}),trait('defiance','Défiance','Defiance','Avantage aux sauvegardes pour éviter ou terminer l’état effrayé.',requiresChoice={'key':'legacy','optionId':'defiance'})],description='Version2022 compatible avec les règles2014. Aucune Tactique de groupe ni Sensibilité au soleil ajoutée depuis Volo.',language='fr')
# Expose the MotM heritage in both the racial summary and its choice controls.
