 {'raceId':'srd51:race:elf','subrace':{'id':'phb14:race:wood-elf','name':{'fr':'Elfe des bois','en':'Wood Elf'},'bonuses':{'wis':1},'speed':35,'proficiencies':['longswords','shortswords','shortbows','longbows'],'traits':[trait('mask-of-the-wild','Cachette naturelle','Mask of the Wild','Vous pouvez tenter de vous cacher même lorsqu’un phénomène naturel ne vous dissimule que partiellement.')] }},
 {'raceId':'srd51:race:elf','subrace':{'id':'phb14:race:drow','name':{'fr':'Elfe noir','en':'Drow'},'bonuses':{'cha':1},'proficiencies':['rapiers','shortswords','hand-crossbows'],'replacesTraits':['darkvision'],'traits':[trait('superior-darkvision','Vision dans le noir36 m','Superior Darkvision120 ft.','Remplace la vision dans le noir de l’elfe.'),trait('sunlight-sensitivity','Sensibilité au soleil','Sunlight Sensitivity','Désavantage aux attaques et tests visuels de Perception lorsque vous ou la cible êtes directement au soleil.')],'spells':[{'id':'srd51:dancing-lights','level':1,'ability':'cha'},{'id':'srd51:faerie-fire','level':3,'ability':'cha','slotLevel':1},{'id':'srd51:darkness','level':5,'ability':'cha','slotLevel':2}]}},
